from fractions import Fraction

def signed(v):
    # "+ 3" or "- 3", for writing a term after another one
    if v < 0:
        return f"- {-v}"
    return f"+ {v}"

def quad(b, c, a):
    top = a * a + b * a + c
    print(f"  (x^2 {signed(b)}x {signed(c)})/(x {signed(-a)}): substitute, top = {top}, bottom = 0")
    if top != 0:
        print(f"  {top}/0: no finite limit")
    else:
        print(f"  0/0: the top is (x {signed(-a)})(x {signed(a + b)}), cancel")
        print(f"  limit = {a} {signed(a + b)} = {2 * a + b}")

def angle(a, b):
    print(f"  sin({a}x)/({b}x) = ({a / b}) * sin({a}x)/({a}x)")
    print(f"  limit = {a / b}")

def degrees(p0, dp, q0, dq):
    print(f"  leading terms {p0}x^{dp} over {q0}x^{dq}")
    if dp == dq:
        print(f"  equal degrees: the limit is {p0 / q0}")
    elif dp < dq:
        print("  bigger bottom: the limit is 0")
    elif (p0 > 0) == (q0 > 0):
        print("  bigger top: the limit is oo")
    else:
        print("  bigger top: the limit is -oo")

def delta(m, eps):
    if m == 0:
        print("  a constant: |f(x) - L| = 0, so any delta works")
    else:
        print(f"  |f(x) - L| = {abs(m)}|x - a| < {eps} when |x - a| < ({eps})/{abs(m)}")
        print(f"  delta = {eps / abs(m)}")

def ivt(p, q, lo, hi):
    flo = lo**3 + p * lo + q
    fhi = hi**3 + p * hi + q
    print(f"  f(x) = x^3 {signed(p)}x {signed(q)}: f({lo}) = {flo}, f({hi}) = {fhi}")
    if flo == 0 or fhi == 0:
        print("  an endpoint is a root")
    elif (flo < 0) != (fhi < 0):
        print(f"  a sign change, and f is continuous, so a root lies in ({lo}, {hi})")
    else:
        print("  no sign change, so the IVT says nothing")

def run(kind, nums):
    if kind == "quad":
        quad(nums[0], nums[1], nums[2])
    elif kind == "angle":
        angle(nums[0], nums[1])
    elif kind == "degrees":
        degrees(nums[0], nums[1], nums[2], nums[3])
    elif kind == "delta":
        delta(nums[0], nums[1])
    else:
        ivt(nums[0], nums[1], nums[2], nums[3])

problems = [
    ("quad", [-5, 6, 3]), ("angle", [5, 2]), ("degrees", [4, 2, 2, 2]),
    ("delta", [5, Fraction("0.1")]), ("ivt", [-2, -5, 2, 3]), ("quad", [1, 1, 2]),
    ("degrees", [-3, 3, 1, 2]), ("delta", [0, Fraction("0.01")]),
    ("ivt", [0, 1, 0, 2]), ("quad", [-2, 1, 1]),
]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Fraction(v) for v in nums]
    text = ""
    for v in nums:
        text = text + f" {v}"
    print(f"Problem {i + 1}: {kind}{text}")
    run(kind, nums)

