from fractions import Fraction

def signed(v):
    # "+ 3" or "- 3", for writing a term after another one
    if v < 0:
        return f"- {-v}"
    return f"+ {v}"

def findk(p, q, c):
    right = c * c + q
    print(f"  right limit and f({c}): ({c})^2 {signed(q)} = {right}")
    print(f"  left limit: {c}k {signed(p)}")
    k = (right - p) / c
    print(f"  {c}k {signed(p)} = {right}, so k = {k}, check: left {k * c + p}, right {right}")

def hole(r, t, s, a):
    print(f"  cancel (x {signed(-r)}): f(x) = (x {signed(-t)})/(x {signed(-s)}) for x != {r}")
    top = a - t
    bottom = a - s
    if a == s:
        if top > 0:
            right, left = "oo", "-oo"
        else:
            right, left = "-oo", "oo"
        print(f"  at {a}: {top}/0, an asymptote: right {right}, left {left}")
    elif a == r:
        print(f"  at {a}: a hole, the limit is {top / bottom} but f({a}) is undefined")
    else:
        print(f"  at {a}: substitute, {top}/{bottom} = {top / bottom}")

def trig(a, b):
    print(f"  (1 - cos({a}x))/({b}x^2) = ({a * a}/{b}) * (1 - cos({a}x))/({a}x)^2")
    print(f"  limit = ({a * a}/{b}) * 1/2 = {a * a / (2 * b)}")

def bisect(N, lo, hi, steps):
    f = lambda x: x * x - N
    print(f"  f(x) = x^2 - {N}: f({lo}) = {f(lo)}, f({hi}) = {f(hi)}")
    if f(lo) * f(hi) >= 0:
        print("  no sign change inside, so bisection doesn't start")
        return
    step = 0
    while step < steps and f((lo + hi) / 2) != 0:
        m = (lo + hi) / 2
        if f(lo) * f(m) < 0:
            hi = m
        else:
            lo = m
        step = step + 1
        print(f"  step {step}: m = {m}, f(m) = {f(m)}, keep [{lo}, {hi}]")
    m = (lo + hi) / 2
    if f(m) == 0:
        print(f"  exact root {m}")
    else:
        print(f"  root within {(hi - lo) / 2} of {m}")

def run(kind, nums):
    if kind == "findk":
        findk(nums[0], nums[1], nums[2])
    elif kind == "hole":
        hole(nums[0], nums[1], nums[2], nums[3])
    elif kind == "trig":
        trig(nums[0], nums[1])
    else:
        bisect(nums[0], nums[1], nums[2], nums[3])

problems = [
    ("findk", [1, -4, 2]), ("hole", [2, -2, -1, 2]), ("hole", [2, -2, -1, -1]),
    ("trig", [4, 1]), ("bisect", [3, 1, 2, 3]), ("findk", [0, 0, -1]),
    ("hole", [2, -2, -1, 0]), ("trig", [-2, 3]), ("bisect", [4, 0, 4, 3]),
]
for i in range(len(problems)):
    kind, nums = problems[i]
    nums = [Fraction(v) for v in nums]
    text = ""
    for v in nums:
        text = text + f" {v}"
    print(f"Problem {i + 1}: {kind}{text}")
    run(kind, nums)

