from fractions import Fraction

def signed(v):
    # "+ 3" or "- 3", for writing a term after another one
    if v < 0:
        return f"- {-v}"
    return f"+ {v}"

def line(m, b, a, eps):
    L = m * a + b
    print(f"  L = {m}({a}) {signed(b)} = {L}, and |f(x) - L| = {abs(m)}|x - a|")
    if m == 0:
        print("  a constant: any delta works")
        return
    d = eps / abs(m)
    print(f"  delta = ({eps})/({abs(m)}) = {d}, edge x = {a + d}: |f - L| = {abs(m * d)}, exactly eps")

def parabola(a, eps):
    K = 2 * abs(a) + 1
    d = min(Fraction(1), eps / K)
    print(f"  cap at 1, so |x {signed(a)}| < {K}, and delta = min(1, ({eps})/{K}) = {d}")
    print(f"  |x^2 - {a * a}| < delta(2|a| + delta) = {d * (2 * abs(a) + d)} <= {eps}")

def cutoff(c, d, r, eps):
    gap = abs(d - c * r)
    print(f"  |f(x) - {c}| = {gap}/(x {signed(r)}) for x > {-r}")
    if gap == 0:
        print(f"  f is the constant {c}: any N works")
    else:
        print(f"  {gap}/(x {signed(r)}) < {eps} when x > {gap}/({eps}) {signed(-r)} = {gap / eps - r}")

